(function (g) {
  const EARTH_KM = 6371;
  function distKm(lon1, lat1, lon2, lat2) {
    const toR = Math.PI / 180;
    const dLat = (lat2 - lat1) * toR;
    const dLon = (lon2 - lon1) * toR;
    const a =
      Math.sin(dLat / 2) ** 2 +
      Math.cos(lat1 * toR) * Math.cos(lat2 * toR) * Math.sin(dLon / 2) ** 2;
    return 2 * EARTH_KM * Math.asin(Math.min(1, Math.sqrt(a)));
  }

  g.FREEWAY = {
    /** 最近國道 CCTV；超過 maxKm 回 null。row = [lon,lat,road,mile,url] */
    nearest(lon, lat, maxKm = 45) {
      const list = g.FREEWAY_CCTV || [];
      let best = null;
      let bestD = Infinity;
      for (let i = 0; i < list.length; i++) {
        const row = list[i];
        const d = distKm(lon, lat, row[0], row[1]);
        if (d < bestD) {
          bestD = d;
          best = row;
        }
      }
      if (!best || bestD > maxKm) return null;
      return {
        lon: best[0],
        lat: best[1],
        road: best[2],
        mile: best[3],
        url: best[4],
        km: Math.round(bestD * 10) / 10
      };
    }
  };
})(window);